# Re-analyzing with CORRECT mapping from demo:
# More frequent color (2 in demo, 5 in task) → 0
# Less frequent color (5 in demo, 4 in task) → pattern color (2 in demo, 4 in task), 
#   with large-component exception where bottom-right pixels also → 0

from collections import Counter

grid = globals()['grid']
H, W = len(grid), len(grid[0])

def get_8way_components(grid, color):
    visited = set()
    components = []

    def bfs(r, c):
        component = []
        queue = [(r, c)]
        while queue:
            cr, cc = queue.pop(0)
            if (cr, cc) in visited:
                continue
            visited.add((cr, cc))
            component.append((cr, cc))
            for dr in range(-1, 2):
                for dc in range(-1, 2):
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] == color and (nr, nc) not in visited:
                        queue.append((nr, nc))
        return component

    for r in range(H):
        for c in range(W):
            if grid[r][c] == color and (r, c) not in visited:
                comp = bfs(r, c)
                if comp:
                    components.append(comp)
    return components

components_4 = get_8way_components(grid, 4)  # less frequent
components_5 = get_8way_components(grid, 5)  # more frequent

# Generate output with component-based rule
def generate_output():
    output_grid = [[0]*W for _ in range(H)]
    size_threshold = 5  # Components >= 5 get split rule

    # Process 5s (more frequent → 0)
    for comp in components_5:
        if len(comp) >= size_threshold:
            # Large 5-component: split (br → 0, other → 0) = all 0
            # Since both br and non-br → 0, this is just all 5s → 0
            for r, c in comp:
                output_grid[r][c] = 0
        else:
            # Small 5-component: all 0
            for r, c in comp:
                output_grid[r][c] = 0

    # Actually, both branches give same result!
    # Let me reconsider the demo rule...

    # Demo (correct): 2→0 (all 2s), 5→2 with exceptions (br→0)
    # So: more-frequent→0, less-frequent→pattern with component-exceptions

    # For task: 5→0 (all 5s would be 0), 4→4 with exceptions (br in large 4-comp → 0)

    # Process 4s (less frequent → 4, with large-component split)
    for comp in components_4:
        if len(comp) >= size_threshold:
            # Large 4-component: split
            min_r, max_r = min(row for row, col in comp), max(row for row, col in comp)
            min_c, max_c = min(col for row, col in comp), max(col for row, col in comp)
            br_threshold_r = (min_r + max_r) / 2
            br_threshold_c = (min_c + max_c) / 2
            for r, c in comp:
                if r >= br_threshold_r and c >= br_threshold_c:
                    output_grid[r][c] = 0  # br → background
                else:
                    output_grid[r][c] = 4  # other → original color
        else:
            # Small 4-component: all 4
            for r, c in comp:
                output_grid[r][c] = 4

    return output_grid

output_grid = generate_output()

print("=== Output with component-based rule (5→0 all, 4→4 with split) ===")
for row in output_grid:
    print(''.join(map(str, row)))
print(f"\nValue counts: 0={sum(r.count(0) for r in output_grid)}, 4={sum(r.count(4) for r in output_grid)}")
